// Scratch: load the real build, lay the P3 dining room's own furniture + lights on it with no runParts lock, save a copy.
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import * as room24 from "/Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/sears-kit/crew/lamp-31/parts/room-24.mjs";
const [src, out, extra] = process.argv.slice(2);
const g = load(src);
